// 5. 核心：精准解析MP3采样率（从文件头字节流中提取，支持MPEG1/2/2.5）
function parseMp3SampleRate(byteStream) {
    try {
        let byteArray = [];
        let byteData;
        let readCount = 0;

        // 读取文件头（最大MAX_READ_BYTES字节，足够解析帧头）
        while (readCount < MAX_READ_BYTES) {
            byteData = byteStream.read();
            if (byteData === -1) break;
            byteArray.push(byteData);
            readCount++;
        }

        // 跳过ID3v2标签（避免标签干扰帧头识别）
        let startIndex = 0;
        if (byteArray.length >= 10 && byteArray[0] === 0x49 && byteArray[1] === 0x44 && byteArray[2] === 0x33) {
            const tagSizeByte1 = byteArray[6] & 0x7F;
            const tagSizeByte2 = byteArray[7] & 0x7F;
            const tagSizeByte3 = byteArray[8] & 0x7F;
            const tagSizeByte4 = byteArray[9] & 0x7F;
            const tagTotalLength = (tagSizeByte1 << 21) + (tagSizeByte2 << 14) + (tagSizeByte3 << 7) + tagSizeByte4;
            startIndex = 10 + tagTotalLength;
        }

        // 遍历字节数组，查找MP3帧头并提取采样率
        for (let i = startIndex; i < byteArray.length - 3; i++) {
            const b1 = byteArray[i];
            const b2 = byteArray[i + 1];
            const b3 = byteArray[i + 2];
            // 帧头标识：0xFF（前8位） + 0xE0~0xF3（接下来4位），共12位1
            if (b1 !== 0xFF || (b2 & 0xE0) !== 0xE0) continue;

            // 解析MPEG版本（2位）
            const mpegVersionBits = (b2 >> 3) & 0x03;
            let mpegVersion = "未知";
            if (mpegVersionBits === 0x00) mpegVersion = "2.5";
            else if (mpegVersionBits === 0x02) mpegVersion = "2";
            else if (mpegVersionBits === 0x03) mpegVersion = "1";
            else continue; // 无效版本，跳过

            // 解析采样率索引（2位），分版本映射真实采样率
            const sampleRateIndex = (b3 >> 2) & 0x03;
            let sampleRateMap = [];
            if (mpegVersion === "1") sampleRateMap = [44100, 48000, 32000];
            else if (mpegVersion === "2") sampleRateMap = [22050, 24000, 16000];
            else if (mpegVersion === "2.5") sampleRateMap = [11025, 12000, 8000];

            const parsedRate = sampleRateMap[sampleRateIndex] || 44100;
            return parsedRate;
        }

        // 未找到帧头，返回默认采样率（确保不影响后续流程）
        return 44100;
    } catch (e) {
        return 44100;
    }
}

