// 函数A：保护已匹配的在线/本地音效（完全对齐原始逻辑：仅换音效，保留前后字符）
function protectMatchedAudios(text) {
    if (!text) {
        return text;
    }
    // 重置缓存和自增ID，避免跨调用污染
    protectedAudioCache = {};
