    var localMatchCount = 0;
    text = text.replace(localAudioReg, function(match) {
        localMatchCount++;
        var placeholder = "###PROTECTED_LOCAL_AUDIO_" + (protectedAudioId++) + "###";
        protectedAudioCache[placeholder] = match; // 原样存储（不trim，保留原始格式）
        return placeholder; // 仅替换音效部分，前后字符不变
    });
    if (localMatchCount > 0) {
    } else {
