}

// 函数B：恢复被保护的音效（完全对齐原始逻辑：原样还原，不改变文本结构）
function restoreProtectedAudios(text) {
    if (!text) {
        return text;
    }
    if (Object.keys(protectedAudioCache).length === 0) {
        return text;
    }

    var restoreCount = 0;

    // 遍历缓存，精准还原（占位符→原始音效，前后字符不变）
    for (var placeholder in protectedAudioCache) {
        if (protectedAudioCache.hasOwnProperty(placeholder)) {
            var originalAudio = protectedAudioCache[placeholder];
            // 正则匹配：全局匹配占位符（不转义#，因为#不是正则特殊字符）
            var placeholderReg = new RegExp(placeholder, "g");
            var hasPlaceholder = placeholderReg.test(text);

            if (hasPlaceholder) {
                text = text.replace(placeholderReg, originalAudio);
                restoreCount++;
            } else {
            }
        }
    }

    // 清空缓存，避免下次污染
    protectedAudioCache = {};
    protectedAudioId = 0;
    return text;
}

// 函数：无API时长估算（无改动，保留原始逻辑）
function estimateDurationByPreview(previewUrl) {
    if (!previewUrl) {
        return null;
    }
    try {
        var response = ttsrv.httpHead(previewUrl);
        var headers = response.headers() || response.getHeaders() || {};

        var contentLength = headers["Content-Length"] || headers["content-length"] || null;
        if (!contentLength || isNaN(parseInt(contentLength, 10))) {
            return null;
        }
        var fileSizeKB = parseInt(contentLength, 10) / 1024;

        var bitrate = 128;
        var durationSec = fileSizeKB / (bitrate / 8);

        var filteredDuration = (durationSec > AUDIO_CONFIG.minDuration && durationSec < AUDIO_CONFIG.maxDuration) 
            ? Math.round(durationSec * 1000) / 1000 
            : null;
        if (filteredDuration) {
        } else {
        }

        return filteredDuration;
    } catch (e) {
        return null;
    }
}



function analyzeAudioDemand(text) {
