        max_tokens: 2000 // 扩容token，确保能容纳多个关键词
    };

    try {
        var response = ttsrv.httpPost(
            AUDIO_CONFIG.zhipuApiEndpoint,
            JSON.stringify(requestData),
            { "Content-Type": "application/json", "Authorization": "Bearer " + AUDIO_CONFIG.apiKey }
        );
        var responseBody = String(response.body().string() || "{}");

        var apiResponse = JSON.parse(responseBody);
        var content = apiResponse.choices?.[0]?.message?.content || "";
        if (!content) throw new Error("API返回content为空");

        // 清理JSON格式（保留原始逻辑）
        var cleanContent = content
            .replace(/```json|```/g, "")
            .replace(/[\u200B\u200C\u200D\uFEFF]/g, "")
            .trim() || '{"soundKeywords":[]}';

        var result;
        try {
            result = JSON.parse(cleanContent);
            // 强制标准化为数组，且仅保留第1项（核心修改：确保1个关键词）
            if (!result.soundKeywords || !Array.isArray(result.soundKeywords)) {
                // 若API仍返回单条对象，手动包装为数组
                if (result.hasOwnProperty("hasOnomatopoeia")) {
                    result = { soundKeywords: [result] };
                } else {
                    result = { soundKeywords: [] };
                }
            } else {
                // 仅保留数组第1项，删除多余关键词
                result.soundKeywords = result.soundKeywords.length > 0 ? [result.soundKeywords[0]] : [];
            }
        } catch (parseErr) {
            // 正则提取所有可能的拟声词/动作词（兜底逻辑，仅保留第1组）
            var keywordMatches = cleanContent.match(/"targetText"\s*:\s*"([^"]*)"/g) || [];
            var soundMatches = cleanContent.match(/"soundKeyword"\s*:\s*"([^"]*)"/g) || [];
            result = { soundKeywords: [] };

            // 仅取第1组匹配项，确保1个关键词
            if (keywordMatches[0] && soundMatches[0]) {
                var targetText = keywordMatches[0]?.replace(/"targetText"\s*:\s*"/, "").replace(/"/, "") || "";
                var soundKeyword = soundMatches[0]?.replace(/"soundKeyword"\s*:\s*"/, "").replace(/"/, "") || "";
                if (targetText) {
                    result.soundKeywords.push({
                        hasOnomatopoeia: true,
                        targetText: targetText,
                        soundKeyword: soundKeyword,
                        contextDesc: "",
                        positionHint: "before"
                    });
                }
            }
        }

        // 过滤无效关键词（保留原始逻辑，不删有效项）
        result.soundKeywords = result.soundKeywords.map(item => {
            var invalidKeywords = ["footsteps", "traffic", "ambient", "background", "stream", "rain", "wind"];
            var soundKeyword = item.soundKeyword || "";
            if (invalidKeywords.some(k => soundKeyword.includes(k))) {
                return null;
            }
            return item;
        }).filter(Boolean);

        // 最终兜底：确保即使过滤后仍仅1个关键词
        if (result.soundKeywords.length > 1) {
