    } catch (apiErr) {
        // 降级逻辑：强制匹配1个关键词（仅保留第1个匹配项）
        var fallbackKeywords = [];
        var onomatopoeiaMap = { 
            "吼": { kw: "roar short", pos: "before" },
            "敲": { kw: "knock short", pos: "after" }
        };

        var textCopy = text;
        var matchedKey = null; // 标记已匹配的关键词，确保仅1个
        // 循环匹配所有关键词，找到第1个就停止
        Object.entries(onomatopoeiaMap).forEach(([key, val]) => {
            if (textCopy.includes(key) && !matchedKey) {
                matchedKey = key;
                fallbackKeywords.push({
                    targetText: key,
                    soundKeyword: val.kw,
                    contextDesc: "",
                    positionHint: val.pos
                });
                textCopy = textCopy.replace(key, "【已匹配】"); // 避免重复匹配
            }
        });

        // 无匹配时补充1个默认关键词（保留原始逻辑）
        if (fallbackKeywords.length === 0) {
            fallbackKeywords.push({
                hasOnomatopoeia: true,
                targetText: text.slice(0, 10),
                soundKeyword: "ambient sound",
                positionHint: "before",
                contextDesc: ""
            });
        }

        return { soundKeywords: fallbackKeywords };
    }
}






