// 函数2：智能音效搜索（完整版，无API依赖+文件头解析采样率）
function searchShortAudio(soundKeyword, contextDesc, originalText, targetExcludeUrls, nextContent) {
    if (!soundKeyword) {
        return null;
    }

    // 定义有效采样率范围（固定6个，方便维护）
    var VALID_SAMPLE_RATES = [24000, 22050, 32000, 44100, 48000, 88200, 16000];

    var fullKeyword = soundKeyword;
    var minDuration = AUDIO_CONFIG.minDuration;
    var maxDuration = AUDIO_CONFIG.maxDuration;
    var targetDuration = AUDIO_CONFIG.targetDuration;
    var encodedKw = encodeURIComponent(fullKeyword);
    var searchUrl = AUDIO_CONFIG.soundApiEndpoint + "/search/text/?" +
        "query=" + encodedKw + "&" +
        "duration=(" + minDuration + "+to+" + maxDuration + ")&" +
        "fields=duration,previews,name,id&" +
        "page_size=" + AUDIO_CONFIG.searchPageSize + "&" +
        "token=" + AUDIO_API_KEY;

    try {
        var searchResponse = ttsrv.httpGet(searchUrl);
        var searchData = JSON.parse(String(searchResponse.body().string() || "{}"));
        if (!searchData || !searchData.results || searchData.results.length === 0) {
            return null;
        }

        // 筛选有效音效（自带时长+估算时长）
        var validSounds = [];
        var hasValidPreciseSound = false;

// 筛选有效音效（核心：时长达标 + 不在不达标网址列表，纯 ES5 写法）
        var validSounds = [];
        var hasValidPreciseSound = false;
        var maxCheckCount = Math.min(searchData.results.length, AUDIO_CONFIG.maxResultsToCheck);

        // 第一步：优先筛选自带明确时长的音效（复用原有时长判断逻辑）
        for (var i = 0; i < maxCheckCount; i++) {
            var sound = searchData.results[i];
            var soundDuration = sound.duration || 0;
            // 复用音效地址获取逻辑（优先 preview-lq-mp3，与之前加密/播放逻辑一致）
            var soundPreviewUrl = sound.previews ? (sound.previews["preview-lq-mp3"] || sound.previews["preview-hq-mp3"]) : "";

            // 双重过滤：①时长在范围内 ②网址不在不达标列表（ES5 循环判断是否存在）
            var isDurationValid = soundDuration >= minDuration && soundDuration <= maxDuration;
            var isUrlValid = true;
            for (var q = 0; q < targetExcludeUrls.length; q++) {
                if (targetExcludeUrls[q] === soundPreviewUrl) {
                    isUrlValid = false;
                    break;
                }
            }

            if (isDurationValid && isUrlValid) {
                validSounds.push({
                    id: sound.id,
                    name: sound.name,
                    duration: soundDuration,
                    durationDiff: Math.abs(soundDuration - targetDuration),
                    previewUrl: soundPreviewUrl
                });
                hasValidPreciseSound = true;
            } else {
                var rejectReason = !isDurationValid ? "时长不达标" : "网址在不达标列表中";
            }
        }

        // 第二步：无自带时长时，启动估算（仍需先过滤不达标网址，复用 estimateDurationByPreview 方法）
        if (!hasValidPreciseSound) {
            for (var j = 0; j < maxCheckCount; j++) {
                var soundItem = searchData.results[j];
                // 跳过已有明确时长的项（与之前逻辑一致）
                if (soundItem.duration) {
                    continue;
                }
                var previewUrl = soundItem.previews ? (soundItem.previews["preview-lq-mp3"] || soundItem.previews["preview-hq-mp3"]) : "";

                // 先过滤不达标网址（ES5 循环判断，减少无效估算）
                var isExcludeUrl = false;
                for (var r = 0; r < targetExcludeUrls.length; r++) {
                    if (targetExcludeUrls[r] === previewUrl) {
                        isExcludeUrl = true;
                        break;
                    }
                }
                if (isExcludeUrl) {
                    continue;
                }

                // 复用原有估算方法（estimateDurationByPreview 不变）
                var estimatedDuration = estimateDurationByPreview(previewUrl);
                if (estimatedDuration && estimatedDuration >= minDuration && estimatedDuration <= maxDuration) {
                    validSounds.push({
                        id: soundItem.id,
                        name: soundItem.name,
                        duration: estimatedDuration,
                        durationDiff: Math.abs(estimatedDuration - targetDuration),
                        previewUrl: previewUrl
                    });
                } else {
                }
            }
        }









        if (!hasValidPreciseSound) {



            for (var j = 0; j < Math.min(searchData.results.length, AUDIO_CONFIG.maxResultsToCheck); j++) {
                var soundItem = searchData.results[j];
                if (soundItem.duration) continue;
                var previewUrl = soundItem.previews?.["preview-lq-mp3"] || soundItem.previews?.["preview-hq-mp3"] || null;
                if (!previewUrl) continue;

                var estimatedDuration = estimateDurationByPreview(previewUrl);
                if (estimatedDuration) {
                    validSounds.push({
                        id: soundItem.id,
                        name: soundItem.name,
                        duration: estimatedDuration,
                        durationDiff: Math.abs(estimatedDuration - targetDuration),
                        previewUrl: previewUrl
                    });
                } else {
                }
            }
        } else {
        }




        // API选优+采样率校验（核心：文件头解析采样率）
        var finalAudio = null;
        if (validSounds.length >= 3) {
            var apiSelected = selectBestAudioByApi(originalText, nextContent, validSounds);
            var retryCount = 0;
            var maxRetry = 3;

            while (apiSelected && retryCount < maxRetry && validSounds.length > 0) {
                // 1. 先查缓存：避免重复解析同一音效的采样率
                var sampleRate = null;
                if (sampleRateCache[apiSelected.id]) {
                    sampleRate = sampleRateCache[apiSelected.id];
                } else {
                    // 2. 缓存未命中：打印音效网址+下载文件头解析采样率
                    // 发送Range请求，仅下载文件头（前MAX_READ_BYTES字节）
                    var headerResponse = ttsrv.httpGet(apiSelected.previewUrl, {
                        "range": `bytes=0-${MAX_READ_BYTES - 1}`,
                        "Accept": "*/*"
                    });
                    if (![200, 206].includes(headerResponse.code())) {
                        throw `文件头请求失败（状态码：${headerResponse.code()}）`;
                    }
                    // 解析文件头采样率
                    var headerByteStream = headerResponse.body().byteStream();
                    sampleRate = parseMp3SampleRate(headerByteStream);
                    // 解析成功后存入缓存
                    sampleRateCache[apiSelected.id] = sampleRate;
                    saveSampleRateCache();
                }

                // 采样率有效性校验
                var isSampleRateValid = sampleRate !== 0 && VALID_SAMPLE_RATES.includes(sampleRate);
                if (!isSampleRateValid) {
                    retryCount++;
                    var reason = sampleRate === 0 ? "无法获取采样率（为0）" : "采样率" + sampleRate + "Hz超出有效范围";
                    validSounds = validSounds.filter(sound => sound.id !== apiSelected.id);
                    apiSelected = validSounds.length >= 1 ? selectBestAudioByApi(originalText, nextContent, validSounds) : null;
                    continue;
                }

                // 采样率达标校验（兼容旧逻辑）
                var isQualified = [24000, 22050, 32000, 44100, 48000, 88200, 16000].includes(sampleRate);
                if (sampleRate === 0) {
                    isQualified = true;
                }

                if (isQualified) {
                    // 采样率绑定标签
                    var sampleRateToTag = {
                        24000: "localSound101",
                        22050: "localSound102",
                        32000: "localSound103",
                        44100: "localSound104",
                        48000: "localSound105",
                        88200: "localSound106",
                        16000: "localSound107"
                    };
                    var smartAudioTagKey = sampleRateToTag[sampleRate] || "localSound107";
                    var smartAudioTagName = SpeechRuleJS.tags[smartAudioTagKey] || smartAudioTagKey;

                    // 加密链接（直接用previewUrl作为下载链接）
                    var realDownloadUrl = apiSelected.previewUrl;
                    var encryptedDownloadUrl = smartAudioTagKey + "|" + realDownloadUrl;

                    // 生成最终音效结果
                    finalAudio = {
                        id: apiSelected.id,
                        name: apiSelected.name,
                        duration: apiSelected.duration,
                        download_url: encryptedDownloadUrl,
                        duration_diff: apiSelected.durationDiff,
                        selected_by: "API（采样率达标+有效：" + sampleRate + "Hz）",
                        sample_rate: sampleRate
                    };
                    break;
                } else {
                    retryCount++;
                    validSounds = validSounds.filter(sound => sound.id !== apiSelected.id);
                    apiSelected = validSounds.length >= 1 ? selectBestAudioByApi(originalText, nextContent, validSounds) : null;
                }
            }

            // 重试后仍无有效采样率的音效
            if (!finalAudio && retryCount >= maxRetry) {
                return null;
            }
        }

        // 兜底逻辑（文件头解析采样率）
        if (!finalAudio) {
            var bestSound = validSounds.reduce((prev, curr) => curr.durationDiff < prev.durationDiff ? curr : prev, validSounds[0]);
            if (!bestSound) {
                return null;
            }

            // 1. 先查缓存：避免重复解析
            var sampleRate = null;
            if (sampleRateCache[bestSound.id]) {
                sampleRate = sampleRateCache[bestSound.id];
            } else {
                // 2. 缓存未命中：打印音效网址+解析文件头
                var headerResponse = ttsrv.httpGet(bestSound.previewUrl, {
                    "range": `bytes=0-${MAX_READ_BYTES - 1}`
                });
                if (![200, 206].includes(headerResponse.code())) {
                    sampleRate = 44100;
                } else {
                    var headerByteStream = headerResponse.body().byteStream();
                    sampleRate = parseMp3SampleRate(headerByteStream);
                    sampleRateCache[bestSound.id] = sampleRate;
                    saveSampleRateCache();
                }
            }

            // 音频链接直接用previewUrl
            var audioLink = bestSound.previewUrl;
            if (!audioLink) {
                return null;
            }

            // 采样率有效性校验
            var isSampleRateValid = sampleRate !== 0 && VALID_SAMPLE_RATES.includes(sampleRate);
            if (!isSampleRateValid) {
                var reason = sampleRate === 0 ? "无法获取采样率（为0）" : "采样率" + sampleRate + "Hz超出有效范围";
                return null;
            }

            // 采样率绑定标签
            var sampleRateToTag = {
                24000: "localSound101",
                22050: "localSound102",
                32000: "localSound103",
                44100: "localSound104",
                48000: "localSound105",
                88200: "localSound106",
                16000: "localSound107"
            };
            var smartAudioTagKey = sampleRateToTag[sampleRate] || "localSound107";
            var encryptedDownloadUrl = smartAudioTagKey + "|" + audioLink;

            finalAudio = {
                id: bestSound.id,
                name: bestSound.name,
                duration: bestSound.duration,
                download_url: encryptedDownloadUrl,
                duration_diff: bestSound.durationDiff,
                selected_by: "原逻辑兜底（采样率有效：" + sampleRate + "Hz）",
                sample_rate: sampleRate
            };
        }

        return finalAudio;
    } catch (err) {
        return null;
    }
}




