// 函数：降级匹配（调整为返回多关键词数组）
function fallbackOnomatopoeiaMatch(text) {
    var onomatopoeiaMap = {
        "轰隆": { keyword: "thunder crash short", position: "before" },
        "滴答": { keyword: "clock tick short", position: "before" },
        "哗啦": { keyword: "water splash short", position: "before" },
        "鸟鸣": { keyword: "bird chirp short", position: "before" },
        "鸟叫": { keyword: "bird singing short", position: "before" },
        "风声": { keyword: "wind blowing short", position: "before" },
        "雨声": { keyword: "rain falling short", position: "before" },
        "雷声": { keyword: "thunder sound short", position: "before" },
        "脚步声": { keyword: "footsteps short", position: "before" },
        "敲门": { keyword: "knocking door short", position: "before" },
        "撞": { keyword: "impact short", position: "before" },
        "踢": { keyword: "kick sound short", position: "before" },
        "打": { keyword: "hit sound short", position: "before" },
        "关（门）": { keyword: "door close short", position: "before" },
        "推": { keyword: "push short", position: "before" }
    };

    var keys = Object.keys(onomatopoeiaMap).sort((a, b) => b.length - a.length);
    var fallbackKeywords = [];
    for (var i = 0; i < keys.length; i++) {
        var target = keys[i];
        if (text.includes(target)) {
            var match = onomatopoeiaMap[target];
            fallbackKeywords.push({
                hasOnomatopoeia: true,
                targetText: target,
                soundKeyword: match.keyword,
                positionHint: match.position,
                contextDesc: ""
            });
        }
    }
    // 无匹配时补充默认关键词
    if (fallbackKeywords.length === 0) {
        fallbackKeywords.push({
            hasOnomatopoeia: true,
            targetText: text.slice(0, 10),
            soundKeyword: "ambient sound",
            positionHint: "before",
            contextDesc: ""
        });
    }
    return { soundKeywords: fallbackKeywords };
}

