CharacterManager.prototype.assignVoice = function(gender, age) {
    var agePriority = {
        '男': ['男青年', '男中年', '少年', '男老年'],
        '女': ['女青年', '少女', '女中年', '女童'],
        '系统': ['系统']
    };

    // 最小改动：拆分候选池，duihua标签在前、硬编在后
    var duihuaCandidates = []; // duihua标签发音人（优先）
    var hardcodeCandidates = []; // 硬编发音人（后置）
    for (var name in GENSHIN_CHARACTERS) {
        if (GENSHIN_CHARACTERS.hasOwnProperty(name)) {
            var info = GENSHIN_CHARACTERS[name];
            if (info.gender === gender && info.age === age) {
                var isUsed = false;
                var checkLen = Math.min(this.characterRecords.length, CONFIG.voiceCheckLimit);
                for (var j = 0; j < checkLen; j++) {
                    if (this.characterRecords[j].voice === info.voice) {
                        isUsed = true;
                        break;
                    }
                    if (this.characterRecords[j].age === '主角' && this.characterRecords[j].voice === info.voice) {
                        isUsed = true;
                        break;
                    }
                }
                var isAvailable = this.isVoiceAvailable(info.voice);
                if (!isUsed && isAvailable) {
                    // 关键判断：是否为duihua标签发音人（通过roleToRootIdMap标记）
                    if (roleToRootIdMap.hasOwnProperty(info.voice)) {
                        duihuaCandidates.push({ name: name, voice: info.voice, matchLevel: 0 });
                    } else {
                        hardcodeCandidates.push({ name: name, voice: info.voice, matchLevel: 0 });
                    }
                }
            }
        }
    }
    // 合并候选池：duihua在前，硬编在后（核心改动）
    var candidates = duihuaCandidates.concat(hardcodeCandidates);


    if (candidates.length === 0 && agePriority[gender]) {
        for (var i = 0; i < agePriority[gender].length; i++) {
            var similarAge = agePriority[gender][i];
            for (var name in GENSHIN_CHARACTERS) {
                if (GENSHIN_CHARACTERS.hasOwnProperty(name)) {
                    var info = GENSHIN_CHARACTERS[name];
                    if (info.gender === gender && info.age === similarAge) {
                        var isUsed = false;
                        var checkLen = Math.min(this.characterRecords.length, CONFIG.voiceCheckLimit);
                        for (var j = 0; j < checkLen; j++) {
                            if (this.characterRecords[j].voice === info.voice) {
                                isUsed = true;
                                break;
                            }
                        }
                        var isAvailable = this.isVoiceAvailable(info.voice);
                        if (!isUsed && isAvailable) {
                            candidates.push({
                                name: name,
                                voice: info.voice,
                                matchLevel: i + 1
                            });
                        }
                    }
                }
            }
            if (candidates.length > 0) break;
        }
    }
    if (candidates.length === 0) {
        return null;
    }
    var that = this;


    candidates.sort(function(a, b) {
        if (a.matchLevel !== b.matchLevel) {
            return a.matchLevel - b.matchLevel;
        }
        var countA = that.voiceUsageMap[a.voice] || 0;
        var countB = that.voiceUsageMap[b.voice] || 0;
        // 核心新增：同使用次数下，duihua标签发音人优先（权重-1）
        var isDuihuaA = roleToRootIdMap.hasOwnProperty(a.voice) ? -1 : 0;
        var isDuihuaB = roleToRootIdMap.hasOwnProperty(b.voice) ? -1 : 0;
        return (countA + isDuihuaA) - (countB + isDuihuaB);
    });

    var selectedVoice = candidates[0].voice;
    this.voiceUsageMap[selectedVoice] = (this.voiceUsageMap[selectedVoice] || 0) + 1;
    this.usedVoices[selectedVoice] = true;
    return selectedVoice;
};

