(function() {
    if (typeof SpeechRuleJS !== 'undefined' && typeof SpeechRuleJS.tags === 'object') {
        for (var num = 4; num <= 600; num++) {
            var tagKey = ("localSound" + num).toString();
            var tagName = ("本地音效" + num).toString();
            SpeechRuleJS.tags[tagKey] = tagName;
        }
    }
})();

